def edit_chars(pair: dict) -> int:
    """Characters changed (difflib, autojunk off: the larger side of each non-equal opcode)."""
    import difflib

    ops = [
        o
        for o in difflib.SequenceMatcher(None, pair["strong"], pair["flawed"], autojunk=False).get_opcodes()
        if o[0] != "equal"
    ]
    return sum(max(o[2] - o[1], o[4] - o[3]) for o in ops)


def _round(backend, system, items, held, strong, slots, tag, max_chars, outcomes):
    """One planting pass over `slots`; pairs over `max_chars` are rejected like a failed filter."""
    edited, log = plant_errors(backend, system, held, strong, slots, 1, PARAPHRASE_REQUEST)
    for tries in log.values():
        for why in tries:
            key = (
                why.split(":")[0].split(" ")[0]
                if why.startswith(("similarity", "length"))
                else why.split(":")[0]
            )
            outcomes[key] = outcomes.get(key, 0) + 1
    kept, too_big = [], 0
    for p in _pairs(items, edited, log, slots, tag):
        if max_chars is not None and edit_chars(p) > max_chars:
            too_big += 1
            continue
        kept.append(p)
    outcomes["over the size gate"] = outcomes.get("over the size gate", 0) + too_big
    return kept

pub fn pod_create(cfg: &Config, profile: &Profile) -> PodCreate {
    let on_volume = profile.network_volume_id.is_some();
    let (image, start, env) = match (&profile.job, &profile.recipe) {
        (Some(j), _) => (j.image.clone(), BOOTSTRAP_JOB, job_env()),
        (None, Some(r)) => match r.engine {
            Engine::Sglang => (r.image.clone(), BOOTSTRAP_SGLANG, engine_env(profile, r)),
        },
        (None, None) => (OLLAMA_IMAGE.to_string(), BOOTSTRAP, ollama_env(profile)),
    };
    PodCreate {
        name: pod_name(cfg, profile),
        image_name: image,
        gpu_type_ids: profile.gpu_type_ids.clone(),
        gpu_type_priority: "custom".into(),
        gpu_count: profile.gpu_count,
        cloud_type: "SECURE".into(),
        support_public_ip: true,
        ports: vec!["22/tcp".into()],
        container_disk_in_gb: profile.container_disk_gb,
        volume_in_gb: (!on_volume).then_some(profile.volume_gb),
        network_volume_id: profile.network_volume_id.clone(),
        volume_mount_path: "/workspace".into(),
        data_center_ids: profile.data_center_id.iter().cloned().collect(),
        allowed_cuda_versions: profile
            .effective_min_cuda()
            .as_deref()
            .and_then(cuda_at_least)
            .unwrap_or_default(),
        docker_entrypoint: vec!["bash".into(), "-c".into()],
        docker_start_cmd: vec![start.into()],
        env,
    }
}

