export function suggestPack(content) {
  const lower = content.toLowerCase();
  const scores = {};

  for (const [packName, keywords] of Object.entries(PACK_KEYWORDS)) {
    let score = 0;
    for (const kw of keywords) {
      if (lower.includes(kw)) score++;
    }
    if (score > 0) scores[packName] = score;
  }

  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  if (sorted.length === 0) return null;

  const [topPack, topScore] = sorted[0];
  const confidence = topScore >= 3 ? "high" : topScore >= 2 ? "medium" : "low";

  return { pack: topPack, confidence, scores };
}

export function suggestPack(content, options = {}) {
  const lower = content.toLowerCase();
  const scores = {};

  for (const [packName, keywords] of Object.entries(PACK_KEYWORDS)) {
    let score = 0;
    for (const kw of keywords) {
      if (lower.includes(kw)) score++;
    }
    if (score > 0) scores[packName] = score;
  }

  const snap = calibrationSnapshot(options);
  const adjusted = {};
  for (const name of Object.keys(scores)) {
    const row = snap.evidence.find((item) => item.pack === name);
    const boost = row && row.status === "measured" ? row.boost : 0;
    adjusted[name] = scores[name] + boost;
  }

  const sorted = Object.entries(adjusted).sort((a, b) => b[1] - a[1]);
  if (sorted.length === 0) return null;

  const topPack = sorted[0][0];
  const keywordScore = scores[topPack];
  const confidence = keywordScore >= 3 ? "high" : keywordScore >= 2 ? "medium" : "low";

  return {
    pack: topPack,
    confidence,
    scores,
    evidence: snap.evidence,
    calibration: snap.disabled ? "off" : (snap.outcomes.length ? "on" : "empty"),
    calibrationText: snap.text,
  };
}

export function juryCheck(critics, items, { seed = DEFAULT_SEED, B = DEFAULT_BOOTSTRAP } = {}) {
  const reports = criticReports(critics, items, seed, B);
  const pairs = diversityMatrix(critics, items);
  const inverted = [];
  for (let i = 0; i < reports.length; i++) {
    const row = reports[i];
    if (row.ci && row.ci.high < 0.5) inverted.push(row.id);
  }
  const duplicates = [];
  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair.errorConsistency !== null && pair.errorConsistency >= DUPLICATE_KAPPA) {
      duplicates.push({ a: pair.a, b: pair.b, errorConsistency: pair.errorConsistency });
    }
  }
  return {
    items: items.length,
    groups: sortedGroups(items).length,
    seed,
    bootstrap: B,
    critics: reports,
    pairs,
    inverted,
    duplicates,
  };
}

export function juryCheck(critics, items, {
  seed = DEFAULT_SEED,
  B = DEFAULT_BOOTSTRAP,
  recipes,
  allowUnproven = false,
  requireRecipe = false,
} = {}) {
  const reports = criticReports(critics, items, seed, B);
  const pairs = diversityMatrix(critics, items);
  const inverted = [];
  for (let i = 0; i < reports.length; i++) {
    const row = reports[i];
    if (row.ci && row.ci.high < 0.5) inverted.push(row.id);
  }
  const duplicates = [];
  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair.errorConsistency !== null && pair.errorConsistency >= DUPLICATE_KAPPA) {
      duplicates.push({ a: pair.a, b: pair.b, errorConsistency: pair.errorConsistency });
    }
  }
  const gate = recipeAssessments(critics, recipes, { allowUnproven, requireRecipe });
  for (let i = 0; i < reports.length; i++) {
    reports[i].recipe = gate.applied ? (gate.byId.get(reports[i].id) || null) : null;
  }
  return {
    items: items.length,
    groups: sortedGroups(items).length,
    seed,
    bootstrap: B,
    critics: reports,
    pairs,
    inverted,
    duplicates,
    excluded: gate.excluded,
    allowUnproven: gate.applied ? allowUnproven === true : false,
    requireRecipe: gate.applied ? requireRecipe === true : false,
  };
}

export function completeStep(run, artifact, note, cwd = process.cwd()) {
  const active = run.steps.find((s) => s.status === "active");
  if (!active) {
    throw new Error("No active step to complete");
  }

  const { validation, buildGateResult, exitConditionResult } = runCompletionGates(active, artifact, cwd, run);
  active.artifactValidation = validation;
  if (buildGateResult) active.buildGateResult = buildGateResult;
  if (exitConditionResult && !exitConditionResult.skipped) {
    active.exitConditionResult = exitConditionResult;
  }
  warnArtifactValidation(validation);
  if (buildGateResult) console.log(formatBuildGateStatus(buildGateResult));

  active.status = "completed";
  active.artifact = artifact;
  active.note = note || null;
  active.completedAt = new Date().toISOString();

  // Check if all steps are done
  const allDone = run.steps.every((s) => s.status === "completed");
  if (allDone) {
    run.status = "completed";
    run.completedAt = new Date().toISOString();
  }

  return active;
}

