/// memory and fallback), and its CUDA floor is the one it was made with; a plan that
/// recorded neither (made before they existed) falls back to the profile's.
pub fn pod_create_for_plan(
    cfg: &Config,
    profile: &Profile,
    gpu_types: &[String],
